package com.rikkeibank.transaction.client;import org.springframework.cloud.openfeign.FeignClient;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.UUID;
@FeignClient(name="account-service")public interface AccountClient{@PostMapping("/internal/accounts/{id}/debit")AccountView debit(@RequestHeader("X-Internal-Key")String key,@PathVariable UUID id,@RequestBody Movement movement);@PostMapping("/internal/accounts/{id}/credit")AccountView credit(@RequestHeader("X-Internal-Key")String key,@PathVariable UUID id,@RequestBody Movement movement);@PostMapping("/internal/accounts/{id}/refund")AccountView refund(@RequestHeader("X-Internal-Key")String key,@PathVariable UUID id,@RequestBody Movement movement);record Movement(UUID operationId,UUID customerId,BigDecimal amount){}record AccountView(UUID id,UUID customerId,BigDecimal balance,String status){}}

